cypress_script:
describe('File Upload Tests', () => {
  it('should successfully upload a file', () => {
    cy.visit('https://the-internet.herokuapp.com/upload');
    cy.get('#file-upload').attachFile('example.txt');
    cy.get('#file-submit').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/upload');
    cy.get('h1').should('contain.text', 'File Uploader');
  });

  it('should fail to upload with no file selected', () => {
    cy.visit('https://the-internet.herokuapp.com/upload');
    cy.get('#file-submit').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/upload');
    cy.get('h1').should('contain.text', 'File Uploader');
  });
});

playwright_script:
import { test } from '@playwright/test';
test.describe('File Upload Tests', () => {
  test('should successfully upload a file', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/upload');
    await page.setInputFiles('#file-upload', 'example.txt');
    await page.click('#file-submit');
    await page.waitForURL('https://the-internet.herokuapp.com/upload');
    await expect(page.locator('h1')).toHaveText('File Uploader');
  });

  test('should fail to upload with no file selected', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/upload');
    await page.click('#file-submit');
    await page.waitForURL('https://the-internet.herokuapp.com/upload');
    await expect(page.locator('h1')).toHaveText('File Uploader');
  });
});
